$('artCanvas').addEventListener('wheel',e=>{if(tool!=='crop'||busy||!media.photo)return;e.preventDefault();if(!wheelEditing){remember();wheelEditing=true;}clearTimeout(wheelTimer);active().state.photoZoom=Math.max(.25,Math.min(6,active().state.photoZoom*(e.deltaY<0?1.05:.95)));renderNow();if(active().state.fit==='cover')clampPhoto();syncControls();requestRender();touch();wheelTimer=setTimeout(()=>{wheelEditing=false;scheduleThumbnails();},250);},{passive:false});
const editing=new Set();
