document.addEventListener('keydown',e=>{if($('clipDialog')?.open){if((e.ctrlKey||e.metaKey)&&['s','o','n','e','d'].includes(e.key.toLowerCase()))e.preventDefault();return;}if(busy)return;const target=document.activeElement,typing=['INPUT','TEXTAREA','SELECT'].includes(target.tagName),key=e.key.toLowerCase(),ctrl=e.ctrlKey||e.metaKey;if(ctrl){if(!window.StudioDesktop){if(key==='s'){e.preventDefault();saveProject();return;}if(key==='o'){e.preventDefault();openProject();return;}if(key==='n'){e.preventDefault();newProject();return;}if(key==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(key==='e'){e.preventDefault();openExport(e.shiftKey);return;}}if(key==='b'&&target===$('headline')){e.preventDefault();$('boldButton').click();return;}if(key==='d'&&!typing){e.preventDefault();selected()?duplicateLayer():duplicateBoard();return;}return;}if(typing)return;if(document.querySelector('dialog[open]'))return;if(key==='v')setTool('select');else if(key==='c')setTool('crop');else if(key==='t'){e.preventDefault();addLayer('text');}else if(key==='delete'||key==='backspace'){e.preventDefault();deleteLayer();}else if(key==='escape')selectLayer(null);else if(['arrowleft','arrowright','arrowup','arrowdown'].includes(key)){const l=selected();if(!l||l.locked)return;e.preventDefault();commit(()=>{const step=e.shiftKey?10:1;l.x+=key==='arrowleft'?-step:key==='arrowright'?step:0;l.y+=key==='arrowup'?-step:key==='arrowdown'?step:0;});}});
