const PROFILE_FIELDS={brandName:'profileBrandName',brandLabel:'profileBrandLabel',tagline:'profileTagline',brandMark:'profileBrandMark',location:'profileLocation',handle:'profileHandle',fontFamily:'profileFontFamily',accent:'profileAccent',background:'profileBackground'};
